from flask import Flask, request
import lxml.etree

app = Flask(__name__)

@app.post("/upload")
def upload():
    '''
    Get the xml_src from the request, parse it and return it as string.
    '''
    xml_src = request.data  # Get raw XML data from request
    try:
        parsed_xml = lxml.etree.fromstring(xml_src)  # Parse using lxml
        return lxml.etree.tostring(parsed_xml).decode()  # Return parsed XML as string
    except lxml.etree.XMLSyntaxError as e:
        return f"Invalid XML: {str(e)}", 400

if __name__ == "__main__":
    app.run()
